    int low = getLowerBound(arr); // e.g. max_element or 0
    int high = getUpperBound(arr); // e.g. sum_elements or max-min
    int ans = -1;

    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (isPossible(arr, mid, k)) {
            ans = mid;        // Record valid candidate
            high = mid - 1;   // Try to minimize further (for min(max))
        } else {
            low = mid + 1;    // Increase threshold
        }
    }
    return ans;
}

bool searchMatrix(vector<vector<int>>& matrix, int target) {
    int m = matrix.size();
    int n = matrix[0].size();
    int low = 0, high = m * n - 1;

    while (low <= high) {
        int mid = low + (high - low) / 2;
        int val = matrix[mid / n][mid % n];
        if (val == target) return true;
        else if (val < target) low = mid + 1;
        else high = mid - 1;
    }
    return false;
}
